values
  ('3bd5c782-d947-45eb-9db2-81728e2735e0', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Floating-point computation', 'This module establishes floating-point computation as the course''s first working framework. It supplies the language and representations needed before the path advances to conditioning and stability.', 0),
  ('4c81caf0-d3ca-47ff-b27d-39defebd164c', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3bd5c782-d947-45eb-9db2-81728e2735e0', 'subtopic'::public.curated_course_node_type, 'Representation', 'Representation gives floating-point computation a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before rounding because that next topic assumes this starting point.', 0),
  ('eeafe7dd-fc3d-4e2c-8324-0c16a77dc751', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3bd5c782-d947-45eb-9db2-81728e2735e0', 'subtopic'::public.curated_course_node_type, 'Rounding', 'Rounding identifies a specific object, distinction, or relationship within floating-point computation. Learners need to recognize and use it before combining this module''s ideas in later work. After representation, rounding supplies what is needed to address cancellation.', 1),
  ('de52a2ee-8042-4c2c-a8bb-fc912238a03f', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3bd5c782-d947-45eb-9db2-81728e2735e0', 'subtopic'::public.curated_course_node_type, 'Cancellation', 'Cancellation identifies a specific object, distinction, or relationship within floating-point computation. Learners need to recognize and use it before combining this module''s ideas in later work. After rounding, cancellation supplies what is needed to address backward error.', 2),
  ('f0a839c3-3bff-4959-b959-46f3326de8d7', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3bd5c782-d947-45eb-9db2-81728e2735e0', 'subtopic'::public.curated_course_node_type, 'Backward error', 'Backward error makes the validity limits of floating-point computation explicit, showing when an otherwise correct method or system can become unreliable. As the final topic in this module, backward error carries the completed idea into conditioning and stability.', 3),
  ('8374908b-abb8-4a58-b09b-33fbb828bb13', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Conditioning and stability', 'This module builds directly on floating-point computation and develops conditioning and stability. It belongs here because its methods and distinctions are prerequisites for root finding.', 1),
  ('e7d43d82-8605-4686-9341-a366cabd2909', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '8374908b-abb8-4a58-b09b-33fbb828bb13', 'subtopic'::public.curated_course_node_type, 'Sensitivity', 'Sensitivity makes the validity limits of conditioning and stability explicit, showing when an otherwise correct method or system can become unreliable. It appears before norms because that next topic assumes this starting point.', 0),
  ('d24b0bbd-9c7c-421c-b3a6-3290b6ebecb2', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '8374908b-abb8-4a58-b09b-33fbb828bb13', 'subtopic'::public.curated_course_node_type, 'Norms', 'Norms identifies a specific object, distinction, or relationship within conditioning and stability. Learners need to recognize and use it before combining this module''s ideas in later work. After sensitivity, norms supplies what is needed to address forward/backward analysis.', 1),
  ('b587979d-5f75-4f2b-911e-bcea165eed5a', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '8374908b-abb8-4a58-b09b-33fbb828bb13', 'subtopic'::public.curated_course_node_type, 'Forward/backward analysis', 'Forward/backward analysis identifies a specific object, distinction, or relationship within conditioning and stability. Learners need to recognize and use it before combining this module''s ideas in later work. After norms, forward/backward analysis supplies what is needed to address experiments.', 2),
  ('f3738317-bd20-47da-8da0-9a7c3ec60484', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '8374908b-abb8-4a58-b09b-33fbb828bb13', 'subtopic'::public.curated_course_node_type, 'Experiments', 'Experiments connects conditioning and stability to observable evidence and defines what a valid measurement or interpretation must support. As the final topic in this module, experiments carries the completed idea into root finding.', 3),
  ('51c0759c-3958-4c6d-bd4c-262d1a6ea158', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Root finding', 'This module builds directly on conditioning and stability and develops root finding. It belongs here because its methods and distinctions are prerequisites for linear systems i.', 2),
  ('d6ad5753-85ee-4824-9b56-c6e4095915f1', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '51c0759c-3958-4c6d-bd4c-262d1a6ea158', 'subtopic'::public.curated_course_node_type, 'Bisection', 'Bisection identifies a specific object, distinction, or relationship within root finding. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before fixed point because that next topic assumes this starting point.', 0),
  ('426fb872-37c5-40dc-9d2a-a1f4c7d00de6', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '51c0759c-3958-4c6d-bd4c-262d1a6ea158', 'subtopic'::public.curated_course_node_type, 'Fixed point', 'Fixed point identifies a specific object, distinction, or relationship within root finding. Learners need to recognize and use it before combining this module''s ideas in later work. After bisection, fixed point supplies what is needed to address newton/secant.', 1),
  ('b953b586-88eb-4f0d-a36f-34adfcb74d30', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '51c0759c-3958-4c6d-bd4c-262d1a6ea158', 'subtopic'::public.curated_course_node_type, 'Newton/secant', 'Newton/secant identifies a specific object, distinction, or relationship within root finding. Learners need to recognize and use it before combining this module''s ideas in later work. After fixed point, newton/secant supplies what is needed to address convergence rates.', 2),
  ('d1bef872-675b-435f-b7a3-fc5722c1f0b2', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '51c0759c-3958-4c6d-bd4c-262d1a6ea158', 'subtopic'::public.curated_course_node_type, 'Convergence rates', 'Convergence rates makes difficult behavior in root finding tractable while exposing the assumptions and accuracy limits used by later methods. After newton/secant, convergence rates supplies what is needed to address safeguards.', 3),
  ('6e256525-b74f-4151-bbb1-1cdbf9f228f8', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '51c0759c-3958-4c6d-bd4c-262d1a6ea158', 'subtopic'::public.curated_course_node_type, 'Safeguards', 'Safeguards identifies a specific object, distinction, or relationship within root finding. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, safeguards carries the completed idea into linear systems i.', 4),
  ('bf76e94a-22b5-4f20-9242-28887e90ef2f', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Linear systems I', 'This module builds directly on root finding and develops linear systems i. It belongs here because its methods and distinctions are prerequisites for linear systems ii.', 3),
  ('7015a44a-a646-4238-90d4-fe5776923edd', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bf76e94a-22b5-4f20-9242-28887e90ef2f', 'subtopic'::public.curated_course_node_type, 'Gaussian elimination', 'Gaussian elimination supplies the causal sequence within linear systems i, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before pivoting because that next topic assumes this starting point.', 0),
  ('26394d08-8704-44b4-99bc-bd0cec501c03', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bf76e94a-22b5-4f20-9242-28887e90ef2f', 'subtopic'::public.curated_course_node_type, 'Pivoting', 'Pivoting identifies a specific object, distinction, or relationship within linear systems i. Learners need to recognize and use it before combining this module''s ideas in later work. After gaussian elimination, pivoting supplies what is needed to address lu.', 1),
  ('9eead2c7-1aa6-4fd6-a732-f21067c77290', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bf76e94a-22b5-4f20-9242-28887e90ef2f', 'subtopic'::public.curated_course_node_type, 'LU', 'LU identifies a specific object, distinction, or relationship within linear systems i. Learners need to recognize and use it before combining this module''s ideas in later work. After pivoting, lu supplies what is needed to address condition numbers.', 2),
  ('9b3cacc5-ccaf-47eb-8a77-e2e8314b8447', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bf76e94a-22b5-4f20-9242-28887e90ef2f', 'subtopic'::public.curated_course_node_type, 'Condition numbers', 'Condition numbers identifies a specific object, distinction, or relationship within linear systems i. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, condition numbers carries the completed idea into linear systems ii.', 3),
  ('30a653cf-b294-4a34-9e36-7bd356f6d187', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Linear systems II', 'This module builds directly on linear systems i and develops linear systems ii. It belongs here because its methods and distinctions are prerequisites for eigenvalue problems.', 4),
  ('dd5ae518-d809-442b-a9d7-4150f9a32915', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '30a653cf-b294-4a34-9e36-7bd356f6d187', 'subtopic'::public.curated_course_node_type, 'Sparse structure', 'Sparse structure identifies a specific object, distinction, or relationship within linear systems ii. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before stationary iterations because that next topic assumes this starting point.', 0),
  ('945fd12c-d5f0-419c-a6a7-d12bc3d8be3d', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '30a653cf-b294-4a34-9e36-7bd356f6d187', 'subtopic'::public.curated_course_node_type, 'Stationary iterations', 'Stationary iterations is an executable part of linear systems ii; its correctness, cost, and failure modes recur in later problems and implementations. After sparse structure, stationary iterations supplies what is needed to address conjugate-gradient concepts.', 1),
  ('83090537-57e4-4b2c-b5dd-3fdaf2e65fc8', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '30a653cf-b294-4a34-9e36-7bd356f6d187', 'subtopic'::public.curated_course_node_type, 'Conjugate-gradient concepts', 'Conjugate-gradient concepts identifies a specific object, distinction, or relationship within linear systems ii. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, conjugate-gradient concepts carries the completed idea into eigenvalue problems.', 2),
  ('3d26e277-fcd9-4e08-b0c9-db2c51f1694f', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Eigenvalue problems', 'This module builds directly on linear systems ii and develops eigenvalue problems. It belongs here because its methods and distinctions are prerequisites for interpolation.', 5),
  ('277e9b3e-df87-40f4-ac68-ce4297ad98f4', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3d26e277-fcd9-4e08-b0c9-db2c51f1694f', 'subtopic'::public.curated_course_node_type, 'Power iteration', 'Power iteration is an executable part of eigenvalue problems; its correctness, cost, and failure modes recur in later problems and implementations. It appears before qr ideas because that next topic assumes this starting point.', 0),
  ('54d41136-9578-4ed3-9c6f-8584317b0070', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3d26e277-fcd9-4e08-b0c9-db2c51f1694f', 'subtopic'::public.curated_course_node_type, 'QR ideas', 'QR ideas identifies a specific object, distinction, or relationship within eigenvalue problems. Learners need to recognize and use it before combining this module''s ideas in later work. After power iteration, qr ideas supplies what is needed to address perturbation.', 1),
  ('c31af67a-7730-4d81-9563-6176666583d1', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3d26e277-fcd9-4e08-b0c9-db2c51f1694f', 'subtopic'::public.curated_course_node_type, 'Perturbation', 'Perturbation identifies a specific object, distinction, or relationship within eigenvalue problems. Learners need to recognize and use it before combining this module''s ideas in later work. After qr ideas, perturbation supplies what is needed to address applications.', 2),
  ('39035126-a303-4f84-b66e-67fe62dc2a40', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '3d26e277-fcd9-4e08-b0c9-db2c51f1694f', 'subtopic'::public.curated_course_node_type, 'Applications', 'Applications identifies a specific object, distinction, or relationship within eigenvalue problems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, applications carries the completed idea into interpolation.', 3),
  ('7cc831f0-1c07-4631-a812-43c9aa397236', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Interpolation', 'This module builds directly on eigenvalue problems and develops interpolation. It belongs here because its methods and distinctions are prerequisites for approximation.', 6),
  ('7d49f195-54a4-4d72-b419-5af715c14c7e', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '7cc831f0-1c07-4631-a812-43c9aa397236', 'subtopic'::public.curated_course_node_type, 'Polynomial forms', 'Polynomial forms identifies a specific object, distinction, or relationship within interpolation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before divided differences because that next topic assumes this starting point.', 0),
  ('ed99fe4e-41b7-4e3a-a07a-e86cc11c736a', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '7cc831f0-1c07-4631-a812-43c9aa397236', 'subtopic'::public.curated_course_node_type, 'Divided differences', 'Divided differences identifies a specific object, distinction, or relationship within interpolation. Learners need to recognize and use it before combining this module''s ideas in later work. After polynomial forms, divided differences supplies what is needed to address chebyshev nodes.', 1),
  ('cca789f5-3687-427f-a8c6-4086d1c09612', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '7cc831f0-1c07-4631-a812-43c9aa397236', 'subtopic'::public.curated_course_node_type, 'Chebyshev nodes', 'Chebyshev nodes identifies a specific object, distinction, or relationship within interpolation. Learners need to recognize and use it before combining this module''s ideas in later work. After divided differences, chebyshev nodes supplies what is needed to address runge phenomenon.', 2),
  ('c0d20255-3f64-467a-8a93-d8e6b30b0c49', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '7cc831f0-1c07-4631-a812-43c9aa397236', 'subtopic'::public.curated_course_node_type, 'Runge phenomenon', 'Runge phenomenon identifies a specific object, distinction, or relationship within interpolation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, runge phenomenon carries the completed idea into approximation.', 3),
  ('bce9ccf1-e8ea-42d2-95b3-f1af0235a59b', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Approximation', 'This module builds directly on interpolation and develops approximation. It belongs here because its methods and distinctions are prerequisites for numerical differentiation and integration.', 7),
  ('09488b6f-6a2b-4ba9-b7d0-778fc3607c8a', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bce9ccf1-e8ea-42d2-95b3-f1af0235a59b', 'subtopic'::public.curated_course_node_type, 'Least squares', 'Least squares identifies a specific object, distinction, or relationship within approximation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before orthogonal polynomials because that next topic assumes this starting point.', 0),
  ('6811cac5-26fa-4709-979e-d0bc7e431559', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bce9ccf1-e8ea-42d2-95b3-f1af0235a59b', 'subtopic'::public.curated_course_node_type, 'Orthogonal polynomials', 'Orthogonal polynomials identifies a specific object, distinction, or relationship within approximation. Learners need to recognize and use it before combining this module''s ideas in later work. After least squares, orthogonal polynomials supplies what is needed to address splines.', 1),
  ('535c6a23-82f2-4278-9f3d-c988599f74af', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bce9ccf1-e8ea-42d2-95b3-f1af0235a59b', 'subtopic'::public.curated_course_node_type, 'Splines', 'Splines identifies a specific object, distinction, or relationship within approximation. Learners need to recognize and use it before combining this module''s ideas in later work. After orthogonal polynomials, splines supplies what is needed to address regularization viewpoint.', 2),
  ('4ef2d4c1-94f3-4449-8a18-8f779a28b3d6', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'bce9ccf1-e8ea-42d2-95b3-f1af0235a59b', 'subtopic'::public.curated_course_node_type, 'Regularization viewpoint', 'Regularization viewpoint identifies a specific object, distinction, or relationship within approximation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, regularization viewpoint carries the completed idea into numerical differentiation and integration.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2e6a8c8b-3d70-47cc-ae6e-ff292cd570e6', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Numerical differentiation and integration', 'This module builds directly on approximation and develops numerical differentiation and integration. It belongs here because its methods and distinctions are prerequisites for initial-value odes.', 8),
  ('063f3efb-d065-48f6-ab92-aa93c941e8a0', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '2e6a8c8b-3d70-47cc-ae6e-ff292cd570e6', 'subtopic'::public.curated_course_node_type, 'Truncation/roundoff', 'Truncation/roundoff identifies a specific object, distinction, or relationship within numerical differentiation and integration. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before newton–cotes because that next topic assumes this starting point.', 0),
  ('361265df-b026-4ace-9693-10ec6f94fda4', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '2e6a8c8b-3d70-47cc-ae6e-ff292cd570e6', 'subtopic'::public.curated_course_node_type, 'Newton–Cotes', 'Newton–Cotes identifies a specific object, distinction, or relationship within numerical differentiation and integration. Learners need to recognize and use it before combining this module''s ideas in later work. After truncation/roundoff, newton–cotes supplies what is needed to address gaussian quadrature.', 1),
  ('b831af28-9cb5-4318-8857-19a9d7b79643', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '2e6a8c8b-3d70-47cc-ae6e-ff292cd570e6', 'subtopic'::public.curated_course_node_type, 'Gaussian quadrature', 'Gaussian quadrature identifies a specific object, distinction, or relationship within numerical differentiation and integration. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, gaussian quadrature carries the completed idea into initial-value odes.', 2),
  ('08a88934-5af7-423f-b67f-6fe39b196fad', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Initial-value ODEs', 'This module builds directly on numerical differentiation and integration and develops initial-value odes. It belongs here because its methods and distinctions are prerequisites for stiffness and boundary-value problems.', 9),
  ('5fd93bb0-54cc-44e0-ad17-781bb97ffca0', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '08a88934-5af7-423f-b67f-6fe39b196fad', 'subtopic'::public.curated_course_node_type, 'Euler', 'Euler identifies a specific object, distinction, or relationship within initial-value odes. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before runge–kutta because that next topic assumes this starting point.', 0),
  ('e7cf0db0-953c-4c81-af84-dc3701a01078', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '08a88934-5af7-423f-b67f-6fe39b196fad', 'subtopic'::public.curated_course_node_type, 'Runge–Kutta', 'Runge–Kutta identifies a specific object, distinction, or relationship within initial-value odes. Learners need to recognize and use it before combining this module''s ideas in later work. After euler, runge–kutta supplies what is needed to address local/global error.', 1),
  ('e948c4d9-1157-4cf0-91e4-822a282f0b02', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '08a88934-5af7-423f-b67f-6fe39b196fad', 'subtopic'::public.curated_course_node_type, 'Local/global error', 'Local/global error makes the validity limits of initial-value odes explicit, showing when an otherwise correct method or system can become unreliable. After runge–kutta, local/global error supplies what is needed to address adaptive steps.', 2),
  ('5eee1b76-aa81-42b9-8e96-7ba06047888e', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '08a88934-5af7-423f-b67f-6fe39b196fad', 'subtopic'::public.curated_course_node_type, 'Adaptive steps', 'Adaptive steps identifies a specific object, distinction, or relationship within initial-value odes. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, adaptive steps carries the completed idea into stiffness and boundary-value problems.', 3),
  ('9590539b-fe77-4912-8816-41ec8c90397b', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'Stiffness and boundary-value problems', 'This module builds directly on initial-value odes and develops stiffness and boundary-value problems. It belongs here because its methods and distinctions are prerequisites for pde and computational synthesis.', 10),
  ('f99059b9-7646-4d6f-8b06-d6a13fb0bae9', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '9590539b-fe77-4912-8816-41ec8c90397b', 'subtopic'::public.curated_course_node_type, 'Implicit methods', 'Implicit methods identifies a specific object, distinction, or relationship within stiffness and boundary-value problems. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before shooting because that next topic assumes this starting point.', 0),
  ('8583d2e9-7ee7-49b5-b9b4-c6bb8b4ad0cc', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '9590539b-fe77-4912-8816-41ec8c90397b', 'subtopic'::public.curated_course_node_type, 'Shooting', 'Shooting identifies a specific object, distinction, or relationship within stiffness and boundary-value problems. Learners need to recognize and use it before combining this module''s ideas in later work. After implicit methods, shooting supplies what is needed to address finite differences.', 1),
  ('9810f50d-4b41-4d39-bae0-9f2203e51621', '9f1068e3-26a5-4135-8f89-d5a36bb55437', '9590539b-fe77-4912-8816-41ec8c90397b', 'subtopic'::public.curated_course_node_type, 'Finite differences', 'Finite differences identifies a specific object, distinction, or relationship within stiffness and boundary-value problems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, finite differences carries the completed idea into pde and computational synthesis.', 2),
  ('f0ab3751-4487-40f5-a1a3-b4b1592a412e', '9f1068e3-26a5-4135-8f89-d5a36bb55437', null, 'topic'::public.curated_course_node_type, 'PDE and computational synthesis', 'This culminating module draws on stiffness and boundary-value problems and develops pde and computational synthesis. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('bf43f874-9e77-4144-a35f-f6fe3f88ebf4', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'f0ab3751-4487-40f5-a1a3-b4b1592a412e', 'subtopic'::public.curated_course_node_type, 'Discretization', 'Discretization identifies a specific object, distinction, or relationship within pde and computational synthesis. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before consistency/stability/convergence because that next topic assumes this starting point.', 0),
  ('d811d7e0-792e-4d9f-b711-6764e4ad0d36', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'f0ab3751-4487-40f5-a1a3-b4b1592a412e', 'subtopic'::public.curated_course_node_type, 'Consistency/stability/convergence', 'Consistency/stability/convergence makes the validity limits of pde and computational synthesis explicit, showing when an otherwise correct method or system can become unreliable. After discretization, consistency/stability/convergence supplies what is needed to address verification.', 1),
  ('43b1c677-d364-4c4b-b5b1-1467de7d986e', '9f1068e3-26a5-4135-8f89-d5a36bb55437', 'f0ab3751-4487-40f5-a1a3-b4b1592a412e', 'subtopic'::public.curated_course_node_type, 'Verification', 'Verification identifies a specific object, distinction, or relationship within pde and computational synthesis. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, verification requires ideas from the complete path to be integrated and transferred.', 2);
